llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Ofloxacin showed absolute oral bioavailability greater than 95% in healthy subjects, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Bumetanide absolute oral bioavailability ranged from 0.72 to 0.96 in normal volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Lurtotecan absolute oral bioavailability was 11.3% ± 5.2 in patients, below the 20% threshold and arguing against high bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-transferability evidence is positive (ofloxacin >95% absolute bioavailability), and additional well-transferred positive records such as bumetanide (72-96%) outweigh the negative records (lurtotecan ~11%, dronedarone ~4%) when considering assay-transfer scores and ordinary-condition absolute measurements. Therefore predict high (F >= 20%) with moderate confidence.",
  "evidence_gaps": [
    "The evidence set includes both high and low absolute bioavailability molecules with relatively close assay-transfer scores, so the transferred prediction is not unambiguous.",
    "Some low-bioavailability records come from patient populations, fasted-state conditions, or virtual PBPK simulations, which are less directly transferable than healthy-subject absolute measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

